#!/usr/bin/env node
import "dotenv/config";
import { readFileSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

// Keep one model definition. PostgreSQL has a separate migration history;
// SQLite's table rebuild migrations cannot be replayed on PostgreSQL.
const root = new URL("../", import.meta.url);
const schema = readFileSync(new URL("prisma/schema.prisma", root), "utf8");
writeFileSync(
  new URL("prisma/schema.postgresql.prisma", root),
  "// Generated by scripts/prisma.mjs from schema.prisma. Do not edit.\n" +
    schema.replace('provider = "sqlite"', 'provider = "postgresql"')
);

const result = spawnSync(
  process.execPath,
  [fileURLToPath(new URL("node_modules/prisma/build/index.js", root)), ...process.argv.slice(2)],
  { cwd: fileURLToPath(root), stdio: "inherit", env: process.env }
);
if (result.error) console.error(result.error.message);
process.exit(result.status ?? 1);
